// ============================================================================
// DLB STANDALONE ADAPTER v1.0 — stable handover point
// ============================================================================
// Package Gast777's already calculated per-device messages into one transaction.
// The standalone DLB approves inputLimit values before any Zendure HTTP write.
if (msg1) msg1.dlb_device_index = 1;
if (msg2) msg2.dlb_device_index = 2;
if (msg3) msg3.dlb_device_index = 3;
msg.dlb_batch = [msg1, msg2, msg3].filter(Boolean);
msg.dlb_adapter_request = true;
msg.dlb_adapter_version = "20260701-NL-Gast777-DLB-Adapter-v1.0-TEST";
return [null, msg, null, null, null, null, null];
